    public Object parseMarket(Object market)
    {
        //
        //     {
        //         "symbol": "CLANKER-USDT",
        //         "baseAsset": "CLANKER",
        //         "marginAsset": "USDT",
        //         "quoteAsset": "USDT",
        //         "contractFactor": "0.01",
        //         "limitMaxQty": "50000",
        //         "limitMinQty": "1",
        //         "marketMaxQty": "10000",
        //         "marketMinQty": "1",
        //         "pricePrecision": "8",
        //         "basePrecision": "8",
        //         "feeRateTaker": "0.0006",
        //         "feeRateMaker": "0.0002",
        //         "liqFeeRate": "0.0006",
        //         "openBuyLimitRateMax": "0.05",
        //         "openSellLimitRateMax": "100",
        //         "openBuyLimitRateMin": "0.98",
        //         "openSellLimitRateMin": "0.05",
        //         "priceOrderPrecision": "2",
        //         "baseShowPrecision": "2",
        //         "maxLeverageLevel": "20",
        //         "volumePrecision": "2",
        //         "maxLimitOrderNum": "200",
        //         "maxPlanOrderNum": "10",
        //         "reverse": false,
        //         "onboardTime": "1763373600000",
        //         "status": "NORMAL"
        //     }
        //
        Object id = this.safeString(market, "symbol");
        Object baseId = this.safeString(market, "baseAsset");
        Object quoteId = this.safeString(market, "quoteAsset");
        Object settleId = this.safeString(market, "marginAsset");
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object settle = this.safeCurrencyCode(settleId);
        Object symbol = Helpers.add(Helpers.add(Helpers.add(Helpers.add(base, "/"), quote), ":"), settle);
        Object inverse = this.safeBool(market, "reverse");
        Object limitMaxQty = this.safeString(market, "limitMaxQty");
        Object marketMaxQty = this.safeString(market, "marketMaxQty");
        Object maxAmountString = Precise.stringMax(limitMaxQty, marketMaxQty);
        Object marketMinQty = this.safeString(market, "marketMinQty");
        Object limitMinQty = this.safeString(market, "limitMinQty");
        Object minAmountString = Precise.stringMin(marketMinQty, limitMinQty);
        Object contractSize = this.safeString(market, "contractFactor");
        Object pricePrecision = this.parsePrecision(this.safeString(market, "priceOrderPrecision"));
        Object rawAmountPrecision = this.parsePrecision(this.safeString(market, "volumePrecision"));
        Object amountPrecision = Precise.stringDiv(rawAmountPrecision, contractSize);
        Object basePrecision = this.parsePrecision(this.safeString(market, "basePrecision"));
        Object taker = this.safeNumber(market, "feeRateTaker");
        Object maker = this.safeNumber(market, "feeRateMaker");
        Object maxLeverage = this.safeNumber(market, "maxLeverageLevel");
        Object status = this.safeString(market, "status");
        final Object finalBase = base;
        final Object finalStatus = status;
        final Object finalInverse = inverse;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "symbol", symbol );
            put( "base", finalBase );
            put( "quote", quote );
            put( "settle", settle );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "settleId", settleId );
            put( "type", "swap" );
            put( "spot", false );
            put( "margin", null );
            put( "swap", true );
            put( "future", false );
            put( "option", false );
            put( "active", Helpers.isEqual(finalStatus, "NORMAL") );
            put( "contract", true );
            put( "linear", !Helpers.isEqual(finalInverse, true) );
            put( "inverse", finalInverse );
            put( "taker", taker );
            put( "maker", maker );
            put( "contractSize", Bydfi.this.parseNumber(contractSize) );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Bydfi.this.parseNumber(amountPrecision) );
                put( "price", Bydfi.this.parseNumber(pricePrecision) );
                put( "base", Bydfi.this.parseNumber(basePrecision) );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", maxLeverage );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", Bydfi.this.parseNumber(minAmountString) );
                    put( "max", Bydfi.this.parseNumber(maxAmountString) );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", Bydfi.this.parse8601(Bydfi.this.safeString(market, "createdAt")) );
            put( "info", market );
        }});
    }

